class Solution { fun intervalIntersection(firstList:Array<IntArray>,secondList:Array<IntArray>):Array<IntArray>{val answer=mutableListOf<IntArray>();var i=0;var j=0;while(i<firstList.size&&j<secondList.size){val low=maxOf(firstList[i][0],secondList[j][0]);val high=minOf(firstList[i][1],secondList[j][1]);if(low<=high)answer.add(intArrayOf(low,high));if(firstList[i][1]<secondList[j][1])i++ else j++};return answer.toTypedArray()} }
